starterCode:
const getNumber = (n) => new Promise((resolve) => setTimeout(() => resolve(n), 10));

async function doubleAsync(n) {
  const x = getNumber(n);
  return x * 2;
}

solution:
const getNumber = (n) => new Promise((resolve) => setTimeout(() => resolve(n), 10));

async function doubleAsync(n) {
  const x = await getNumber(n);
  return x * 2;
}

